/**
 * NotificationPort — the unified interface that core orchestrator logic depends on.
 *
 * Core code must never import Slack, Redis, or formatter modules directly.
 * All notification paths go through this interface.
 */

import type {
  FeatureTrigger,
  FeatureContext,
  TaskTrigger,
  TaskContext,
} from "./notification.types.js";

export interface NotificationPort {
  /** Post or update a feature-level Slack message. */
  postFeatureMessage(
    featureId: string,
    trigger: FeatureTrigger,
    context: FeatureContext,
  ): Promise<void>;

  /** Post the final feature message and clean up the feature thread mapping. */
  closeFeatureThread(featureId: string, context: FeatureContext): Promise<void>;

  /** Post or update a task-level Slack message. */
  postTaskMessage(
    featureId: string,
    taskId: string,
    trigger: TaskTrigger,
    context: TaskContext,
  ): Promise<void>;

  /** Post the final task message and clean up the task thread mapping. */
  closeTaskThread(
    featureId: string,
    taskId: string,
    context: TaskContext,
  ): Promise<void>;
}
/**
 * Shared types for the threaded Slack notification system.
 *
 * Pure data — no I/O, no imports from Slack or Redis modules.
 */

// ── Feature triggers ──────────────────────────────────────────────────────────

export type FeatureTrigger =
  | "feature_start"
  | "feature_summary_changed"
  | "handoff_submitted"
  | "feature_completed";

// ── Task triggers ─────────────────────────────────────────────────────────────

export type TaskTrigger =
  | "task_start"
  | "task_status_changed"
  | "task_pr_changed"
  | "task_review_changed"
  | "task_completed";

// ── Feature context ───────────────────────────────────────────────────────────

/** Full current feature state snapshot passed to feature formatters. */
export interface FeatureContext {
  title: string;
  status: string;
  /** Present when status is active/in_progress. Omit or null when not active. */
  nextAction?: string | null;
  /** Present when status is blocked. */
  blockedReason?: string | null;
  /** Present when status is in_handoff. */
  handoff?: string | null;
  /** URL or identifier of the feature-level PR. Present when set. */
  featurePr?: string | null;
  totalTaskCount: number;
  lastUpdatedAt?: string | null;
}

/** Changed fields for a feature event — only fields that changed for this event. */
export interface FeatureChangedFields {
  status?: string;
  blockedReason?: string | null;
  handoff?: string | null;
  featurePr?: string | null;
  lastUpdatedAt?: string | null;
}

// ── Task context ──────────────────────────────────────────────────────────────

/** PR info for a task. */
export interface TaskPrInfo {
  url: string;
  status: string;
}

/** Full current task state snapshot passed to task formatters. */
export interface TaskContext {
  title: string;
  status: string;
  repo: string;
  branch: string;
  /** Email from execution.last_updated_by. */
  lastUpdatedBy?: string | null;
  /** Present when PR has been opened. */
  pr?: TaskPrInfo | null;
  /** Present when task is blocked. */
  blockedReason?: string | null;
  lastUpdatedAt?: string | null;
}

/** Changed fields for a task event — only fields that changed for this event. */
export interface TaskChangedFields {
  status?: string;
  pr?: TaskPrInfo | null;
  blockedReason?: string | null;
  reviewStatus?: string | null;
  lastUpdatedAt?: string | null;
  lastUpdatedBy?: string | null;
}

