export class RedisThreadStore implements NotificationThreadStorePort {
  private client: RedisClientType;
  private connected = false;

  constructor(redisUrl: string) {
    this.client = createClient({ url: redisUrl }) as RedisClientType;
  }

  private async ensureConnected(): Promise<void> {
    if (!this.connected) {
      await this.client.connect();
      this.connected = true;
    }
  }

  async getFeatureThread(workspaceId: string, featureId: string): Promise<string | null> {
    await this.ensureConnected();
    const key = featureKey(workspaceId, featureId);
    return this.client.get(key);
  }

  async setFeatureThread(workspaceId: string, featureId: string, threadTs: string): Promise<void> {
    await this.ensureConnected();
    const key = featureKey(workspaceId, featureId);
    await this.client.set(key, threadTs);
  }

  async deleteFeatureThread(workspaceId: string, featureId: string): Promise<void> {
    await this.ensureConnected();
    const key = featureKey(workspaceId, featureId);
    await this.client.del(key);
  }

  async getTaskThread(workspaceId: string, featureId: string, taskId: string): Promise<string | null> {
    await this.ensureConnected();
    const key = taskKey(workspaceId, featureId, taskId);
    return this.client.get(key);
  }

  async setTaskThread(workspaceId: string, featureId: string, taskId: string, threadTs: string): Promise<void> {
    await this.ensureConnected();
    const key = taskKey(workspaceId, featureId, taskId);
    await this.client.set(key, threadTs);
