import { readFileSync } from "node:fs";
import { parse as parseYaml } from "yaml";
import { workspaceYamlPath } from "../paths.js";
import { parseGitHubCoords } from "../claim/open-workspace-pr.js";
import type { ModelPolicy } from "./resolve-model-policy.js";

type RepoEntry = { id: string; github: string; local_path?: string; base_branch?: string };

function readWorkspaceRepos(workspaceRoot: string): RepoEntry[] {
  const yaml = parseYaml(
    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
  ) as { repos: RepoEntry[] };
  return yaml.repos;
}

function findRepo(workspaceRoot: string, repoId: string): RepoEntry {
  const repos = readWorkspaceRepos(workspaceRoot);
  const repo = repos.find((r) => r.id === repoId);
  if (!repo) throw new Error(`Repo "${repoId}" not found in workspace.yaml`);
  return repo;
}

export function resolveRepoLocalPath(workspaceRoot: string, repoId: string): string {
  const repo = findRepo(workspaceRoot, repoId);
  if (!repo.local_path?.startsWith("env:")) {
    throw new Error(`Repo "${repoId}" has no "local_path: env:<VAR>" declaration.`);
  }
  const envVar = repo.local_path.slice(4);
  const val = process.env[envVar];
  if (!val) throw new Error(`Env var ${envVar} is not set for repo "${repoId}".`);
  return val;
}

export function resolveRepoBaseBranch(workspaceRoot: string, repoId: string): string {
  const repo = findRepo(workspaceRoot, repoId);
  return repo.base_branch ?? "main";
}

export function resolveRepoGitUrl(workspaceRoot: string, repoId: string): string {
  const repo = findRepo(workspaceRoot, repoId);
  return repo.github;
}

export function loadWorkspaceModelPolicy(workspaceRoot: string): ModelPolicy {
  const yaml = parseYaml(
    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
  ) as { model_policy?: Partial<ModelPolicy> };
  const defaultPhase = { allowed: ["claude-sonnet-4-6"], default: "claude-sonnet-4-6" };
  const defaults: ModelPolicy = {
    implementation: defaultPhase,
    self_review: defaultPhase,
    pr_description: defaultPhase,
    suggested_next_step: { allowed: ["claude-haiku-4-5-20251001"], default: "claude-haiku-4-5-20251001" },
    conflict_resolution: defaultPhase,
  };
  if (!yaml.model_policy) return defaults;
  return {
    implementation: yaml.model_policy.implementation ?? defaults.implementation,
    self_review: yaml.model_policy.self_review ?? defaults.self_review,
    pr_description: yaml.model_policy.pr_description ?? defaults.pr_description,
    suggested_next_step: yaml.model_policy.suggested_next_step ?? defaults.suggested_next_step,
    conflict_resolution: yaml.model_policy.conflict_resolution ?? defaults.conflict_resolution,
  };
}

export interface WorkspaceNotificationConfig {
  slack: {
    channelId: string;
  };
}

export function loadWorkspaceNotificationConfig(
  workspaceRoot: string,
): WorkspaceNotificationConfig | null {
  let raw: unknown;
  try {
    raw = parseYaml(readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"));
  } catch {
    return null;
  }
  if (!raw || typeof raw !== "object") return null;
  const doc = raw as Record<string, unknown>;
  const notifications = doc["notifications"];
  if (!notifications || typeof notifications !== "object") return null;
  const slack = (notifications as Record<string, unknown>)["slack"];
  if (!slack || typeof slack !== "object") return null;
  const channelId = (slack as Record<string, unknown>)["channel_id"];
  if (typeof channelId !== "string" || !channelId) return null;
  return { slack: { channelId } };
}

export function parseManagementRepoCoords(
  workspaceRoot: string,
): { owner: string; repo: string; baseBranch: string; repoUrl: string } {
  const yaml = parseYaml(
    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
  ) as { management_repo: string; repos: RepoEntry[] };
  const mgmtId = yaml.management_repo;
  const mgmtRepo = yaml.repos.find((r) => r.id === mgmtId);
  if (!mgmtRepo) throw new Error(`Management repo "${mgmtId}" not found in workspace.yaml`);
  const { owner, repo } = parseGitHubCoords(mgmtRepo.github);
  return { owner, repo, baseBranch: mgmtRepo.base_branch ?? "main", repoUrl: mgmtRepo.github };
}

