/**
 * ThreadedSlackNotifier — adapter that implements NotificationPort by delegating
 * all calls to ThreadedNotificationService.
 *
 * Instantiated at startup and injected wherever NotificationPort is required.
 * The old slack-task-notifier.ts and post-task-slack.ts are the legacy webhook
 * adapters; this is the threaded replacement.
 */

import type { NotificationPort } from "../notifications/notification.port.js";
import type { FeatureTrigger, FeatureContext, TaskTrigger, TaskContext } from "../notifications/notification.types.js";
import { ThreadedNotificationService } from "../notifications/threaded-notification-service.js";

export class ThreadedSlackNotifier implements NotificationPort {
  constructor(private readonly service: ThreadedNotificationService) {}

  postFeatureMessage(
    featureId: string,
    trigger: FeatureTrigger,
    context: FeatureContext,
  ): Promise<void> {
    return this.service.postFeatureMessage(featureId, trigger, context);
  }

  closeFeatureThread(featureId: string, context: FeatureContext): Promise<void> {
    return this.service.closeFeatureThread(featureId, context);
  }

  postTaskMessage(
    featureId: string,
    taskId: string,
    trigger: TaskTrigger,
    context: TaskContext,
  ): Promise<void> {
    return this.service.postTaskMessage(featureId, taskId, trigger, context);
  }

  closeTaskThread(
    featureId: string,
    taskId: string,
    context: TaskContext,
  ): Promise<void> {
    return this.service.closeTaskThread(featureId, taskId, context);
  }
}

/**
 * NullNotifier — no-op adapter used when Slack/Redis config is absent.
 * All calls succeed silently without posting anything to Slack.
 */
export class NullNotifier implements NotificationPort {
  async postFeatureMessage(): Promise<void> {}
  async closeFeatureThread(): Promise<void> {}
  async postTaskMessage(): Promise<void> {}
  async closeTaskThread(): Promise<void> {}
}

