import { describe, it, expect, vi, beforeEach } from "vitest";
import {
  ThreadedNotificationService,
  type NotificationEvent,
  type NotificationServiceDeps,
} from "../../src/notifications/threaded-notification-service.js";
import { InMemoryThreadStore } from "../../src/adapters/in-memory-thread-store.js";
import type { SlackWebApiClient } from "../../src/slack/slack-web-api-client.js";
import type { FeatureContext, TaskContext } from "../../src/notifications/notification.types.js";

// ── Test fixtures ──────────────────────────────────────────────────────────────

const WORKSPACE_ID = "ws-test";
const FEATURE_ID = "my-feature";
const TASK_ID = "T1";

const FEATURE_CTX: FeatureContext = {
  title: "My Feature",
  status: "in_implementation",
  totalTaskCount: 5,
  lastUpdatedAt: "2026-05-23T10:00:00Z",
};

const TASK_CTX: TaskContext = {
  title: "My Task",
  status: "in_progress",
  repo: "workflow",
  branch: "feature/my-feature-T1",
  lastUpdatedBy: "agent@example.com",
};

// ── Mock Slack client builder ──────────────────────────────────────────────────

function makeMockSlack(postTs = "1234567890.001000") {
  return {
    postMessage: vi.fn().mockResolvedValue({ ts: postTs, channel: "C123" }),
    updateMessage: vi.fn().mockResolvedValue(undefined),
  } as unknown as SlackWebApiClient;
}

// ── Service builder ────────────────────────────────────────────────────────────

function makeService(
  slack: SlackWebApiClient | null,
  store: InMemoryThreadStore | null,
  events: NotificationEvent[] = [],
): ThreadedNotificationService {
  const deps: NotificationServiceDeps = {
    slack,
    store,
    workspaceId: WORKSPACE_ID,
    emit: (e) => events.push(e),
  };
  return new ThreadedNotificationService(deps);
}

// ══════════════════════════════════════════════════════════════════════════════
// ensureFeatureThread
// ══════════════════════════════════════════════════════════════════════════════

describe("ensureFeatureThread", () => {
  it("creates a new feature thread when key is absent", async () => {
    const slack = makeMockSlack("ts-feat-001");
    const store = new InMemoryThreadStore();
    const events: NotificationEvent[] = [];
    const svc = makeService(slack, store, events);

    const ts = await svc.ensureFeatureThread(FEATURE_ID, FEATURE_CTX);

    expect(ts).toBe("ts-feat-001");
    expect(slack.postMessage).toHaveBeenCalledOnce();
    const posted = (slack.postMessage as ReturnType<typeof vi.fn>).mock.calls[0];
    expect(posted[0]).toContain("Feature: My Feature");
    expect(posted[1]).toBeUndefined(); // no threadTs — top-level create

    const stored = await store.getFeatureThread(WORKSPACE_ID, FEATURE_ID);
    expect(stored).toBe("ts-feat-001");

    expect(events).toContainEqual({
      type: "feature_slack_thread_created",
      featureId: FEATURE_ID,
      threadTs: "ts-feat-001",
    });
  });

  it("is idempotent — reuses existing thread_ts and does not call postMessage again", async () => {
    const slack = makeMockSlack("ts-feat-001");
    const store = new InMemoryThreadStore();
    await store.setFeatureThread(WORKSPACE_ID, FEATURE_ID, "ts-feat-001");
    const events: NotificationEvent[] = [];
    const svc = makeService(slack, store, events);

    const ts = await svc.ensureFeatureThread(FEATURE_ID, FEATURE_CTX);

    expect(ts).toBe("ts-feat-001");
    expect(slack.postMessage).not.toHaveBeenCalled();
    expect(events.some((e) => e.type === "feature_slack_thread_created")).toBe(false);
  });

  it("emits skip event when Slack is not configured", async () => {
    const events: NotificationEvent[] = [];
    const svc = makeService(null, null, events);

    const ts = await svc.ensureFeatureThread(FEATURE_ID, FEATURE_CTX);

    expect(ts).toBeNull();
    expect(events).toContainEqual({
      type: "slack_notification_skipped",
      reason: "slack_not_configured",
    });
  });

  it("emits redis_operation_failed when store.getFeatureThread throws", async () => {
    const slack = makeMockSlack();
    const store = {
      getFeatureThread: vi.fn().mockRejectedValue(new Error("Redis down")),
      setFeatureThread: vi.fn(),
      deleteFeatureThread: vi.fn(),
      getTaskThread: vi.fn(),
      setTaskThread: vi.fn(),
      deleteTaskThread: vi.fn(),
      deleteAllTaskThreads: vi.fn(),
    };
    const events: NotificationEvent[] = [];
    const svc = makeService(slack, store as unknown as InMemoryThreadStore, events);

    const ts = await svc.ensureFeatureThread(FEATURE_ID, FEATURE_CTX);

    expect(ts).toBeNull();
    expect(events[0]).toMatchObject({
      type: "redis_operation_failed",
      operation: "getFeatureThread",
    });
  });
});

// ══════════════════════════════════════════════════════════════════════════════
// ensureTaskThread
// ══════════════════════════════════════════════════════════════════════════════

describe("ensureTaskThread", () => {
  it("creates a new task thread when key is absent", async () => {
    const slack = makeMockSlack("ts-task-001");
    const store = new InMemoryThreadStore();
    const events: NotificationEvent[] = [];
    const svc = makeService(slack, store, events);

    const ts = await svc.ensureTaskThread(FEATURE_ID, TASK_ID, TASK_CTX);

    expect(ts).toBe("ts-task-001");
    expect(slack.postMessage).toHaveBeenCalledOnce();
    const posted = (slack.postMessage as ReturnType<typeof vi.fn>).mock.calls[0];
    expect(posted[0]).toContain("Task: My Task");
    // Task thread is top-level — no thread_ts passed
    expect(posted[1]).toBeUndefined();

    const stored = await store.getTaskThread(WORKSPACE_ID, FEATURE_ID, TASK_ID);
    expect(stored).toBe("ts-task-001");

    expect(events).toContainEqual({
      type: "task_slack_thread_created",
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      threadTs: "ts-task-001",
    });
  });

  it("is idempotent — reuses existing task thread_ts", async () => {
    const slack = makeMockSlack();
    const store = new InMemoryThreadStore();
    await store.setTaskThread(WORKSPACE_ID, FEATURE_ID, TASK_ID, "ts-task-001");
    const events: NotificationEvent[] = [];
    const svc = makeService(slack, store, events);

    const ts = await svc.ensureTaskThread(FEATURE_ID, TASK_ID, TASK_CTX);

    expect(ts).toBe("ts-task-001");
    expect(slack.postMessage).not.toHaveBeenCalled();
  });

  it("emits skip event when not configured", async () => {
    const events: NotificationEvent[] = [];
    const svc = makeService(null, null, events);

    const ts = await svc.ensureTaskThread(FEATURE_ID, TASK_ID, TASK_CTX);

    expect(ts).toBeNull();
    expect(events[0]).toMatchObject({ type: "slack_notification_skipped" });
  });

  it("emits redis_operation_failed when store.getTaskThread throws", async () => {
    const slack = makeMockSlack();
    const store = {
      getFeatureThread: vi.fn(),
      setFeatureThread: vi.fn(),
      deleteFeatureThread: vi.fn(),
      getTaskThread: vi.fn().mockRejectedValue(new Error("Redis down")),
      setTaskThread: vi.fn(),
      deleteTaskThread: vi.fn(),
      deleteAllTaskThreads: vi.fn(),
    };
    const events: NotificationEvent[] = [];
    const svc = makeService(slack, store as unknown as InMemoryThreadStore, events);

    const ts = await svc.ensureTaskThread(FEATURE_ID, TASK_ID, TASK_CTX);

    expect(ts).toBeNull();
    expect(events[0]).toMatchObject({
      type: "redis_operation_failed",
      operation: "getTaskThread",
    });
  });
});

// ══════════════════════════════════════════════════════════════════════════════
// postFeatureMessage — feature_start
// ══════════════════════════════════════════════════════════════════════════════

describe("postFeatureMessage — feature_start", () => {
  it("calls ensureFeatureThread (creates top-level message) without calling chat.update", async () => {
    const slack = makeMockSlack("ts-feat-100");
    const store = new InMemoryThreadStore();
    const events: NotificationEvent[] = [];
    const svc = makeService(slack, store, events);

    await svc.postFeatureMessage(FEATURE_ID, "feature_start", FEATURE_CTX);

    expect(slack.postMessage).toHaveBeenCalledOnce();
    expect(slack.updateMessage).not.toHaveBeenCalled();
    expect(events).toContainEqual({
      type: "feature_slack_thread_created",
      featureId: FEATURE_ID,
      threadTs: "ts-feat-100",
    });
  });

  it("is idempotent when thread already exists — no second postMessage", async () => {
    const slack = makeMockSlack();
    const store = new InMemoryThreadStore();
    await store.setFeatureThread(WORKSPACE_ID, FEATURE_ID, "ts-feat-100");
    const svc = makeService(slack, store);

    await svc.postFeatureMessage(FEATURE_ID, "feature_start", FEATURE_CTX);

    expect(slack.postMessage).not.toHaveBeenCalled();
    expect(slack.updateMessage).not.toHaveBeenCalled();
  });
});

// ══════════════════════════════════════════════════════════════════════════════
// postFeatureMessage — subsequent triggers
// ══════════════════════════════════════════════════════════════════════════════

describe("postFeatureMessage — subsequent triggers (feature_summary_changed, handoff_submitted, feature_completed)", () => {
  it("calls chat.update on top-level message then posts a reply", async () => {
    const slack = makeMockSlack("ts-reply-001");
    const store = new InMemoryThreadStore();
    await store.setFeatureThread(WORKSPACE_ID, FEATURE_ID, "ts-feat-100");
    const events: NotificationEvent[] = [];
    const svc = makeService(slack, store, events);

    await svc.postFeatureMessage(FEATURE_ID, "feature_summary_changed", {
      ...FEATURE_CTX,
      status: "blocked",
      blockedReason: "waiting on external dependency",
    });

    expect(slack.updateMessage).toHaveBeenCalledOnce();
    const updateArgs = (slack.updateMessage as ReturnType<typeof vi.fn>).mock.calls[0];
    expect(updateArgs[0]).toBe("ts-feat-100");
    expect(updateArgs[1]).toContain("Feature: My Feature");
    expect(updateArgs[1]).toContain("Status: :warning: blocked");
    expect(updateArgs[1]).toContain("Blocked: waiting on external dependency");

    expect(slack.postMessage).toHaveBeenCalledOnce();
    const replyArgs = (slack.postMessage as ReturnType<typeof vi.fn>).mock.calls[0];
    expect(replyArgs[0]).toContain("Type: feature_summary_changed");
    expect(replyArgs[1]).toEqual({ threadTs: "ts-feat-100" });

    expect(events).toContainEqual({
      type: "feature_slack_thread_updated",
      featureId: FEATURE_ID,
      threadTs: "ts-feat-100",
    });
    expect(events).toContainEqual({
      type: "feature_slack_reply_posted",
      featureId: FEATURE_ID,
      threadTs: "ts-feat-100",
    });
  });

  it("lazily creates thread when key is missing for a non-start trigger", async () => {
    const slack = makeMockSlack("ts-feat-lazy");
    const store = new InMemoryThreadStore();
    const events: NotificationEvent[] = [];
    const svc = makeService(slack, store, events);

