      type: "feature_slack_thread_updated",
      featureId: FEATURE_ID,
      threadTs: "ts-feat-100",
    });
    expect(events).toContainEqual({
      type: "feature_slack_reply_posted",
      featureId: FEATURE_ID,
      threadTs: "ts-feat-100",
    });
  });

  it("lazily creates thread when key is missing for a non-start trigger", async () => {
    const slack = makeMockSlack("ts-feat-lazy");
    const store = new InMemoryThreadStore();
    const events: NotificationEvent[] = [];
    const svc = makeService(slack, store, events);

    // No thread exists yet — lazy creation
    await svc.postFeatureMessage(FEATURE_ID, "feature_summary_changed", FEATURE_CTX);

    expect(slack.postMessage).toHaveBeenCalledOnce(); // creates thread
    expect(slack.updateMessage).not.toHaveBeenCalled(); // newly created — no update needed
    expect(events).toContainEqual({
      type: "feature_slack_thread_created",
      featureId: FEATURE_ID,
      threadTs: "ts-feat-lazy",
    });
  });

  it("handoff_submitted calls chat.update + reply with handoff fields", async () => {
    const slack = makeMockSlack();
    const store = new InMemoryThreadStore();
    await store.setFeatureThread(WORKSPACE_ID, FEATURE_ID, "ts-feat-100");
    const svc = makeService(slack, store);

    await svc.postFeatureMessage(FEATURE_ID, "handoff_submitted", {
      ...FEATURE_CTX,
      status: "in_handoff",
      handoff: "https://github.com/org/repo/pull/42",
    });

    expect(slack.updateMessage).toHaveBeenCalledOnce();
    const updateText = (slack.updateMessage as ReturnType<typeof vi.fn>).mock.calls[0][1] as string;
    expect(updateText).toContain("Status: :handshake: in_handoff");
    expect(updateText).toContain("Handoff: https://github.com/org/repo/pull/42");
    expect(slack.postMessage).toHaveBeenCalledOnce();
  });

  it("does not call Slack when not configured", async () => {
    const events: NotificationEvent[] = [];
    const svc = makeService(null, null, events);

    await svc.postFeatureMessage(FEATURE_ID, "feature_summary_changed", FEATURE_CTX);

    expect(events[0]).toMatchObject({ type: "slack_notification_skipped" });
  });
});

// ══════════════════════════════════════════════════════════════════════════════
// postTaskMessage — task_start
// ══════════════════════════════════════════════════════════════════════════════

describe("postTaskMessage — task_start", () => {
  it("creates the task thread without calling chat.update", async () => {
    const slack = makeMockSlack("ts-task-100");
    const store = new InMemoryThreadStore();
    const events: NotificationEvent[] = [];
    const svc = makeService(slack, store, events);

    await svc.postTaskMessage(FEATURE_ID, TASK_ID, "task_start", TASK_CTX);

    expect(slack.postMessage).toHaveBeenCalledOnce();
    expect(slack.updateMessage).not.toHaveBeenCalled();
    const posted = (slack.postMessage as ReturnType<typeof vi.fn>).mock.calls[0];
    expect(posted[0]).toContain("Task: My Task");
    expect(posted[0]).toContain("Repo: workflow");
    expect(posted[0]).toContain("Branch: feature/my-feature-T1");
    expect(posted[1]).toBeUndefined(); // top-level create — no thread_ts

    expect(events).toContainEqual({
      type: "task_slack_thread_created",
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      threadTs: "ts-task-100",
    });
  });

  it("is idempotent — no second create when thread already exists", async () => {
    const slack = makeMockSlack();
    const store = new InMemoryThreadStore();
    await store.setTaskThread(WORKSPACE_ID, FEATURE_ID, TASK_ID, "ts-task-100");
    const svc = makeService(slack, store);

    await svc.postTaskMessage(FEATURE_ID, TASK_ID, "task_start", TASK_CTX);

    expect(slack.postMessage).not.toHaveBeenCalled();
  });
});

// ══════════════════════════════════════════════════════════════════════════════
// postTaskMessage — subsequent triggers
// ══════════════════════════════════════════════════════════════════════════════

describe("postTaskMessage — subsequent triggers", () => {
  it("calls chat.update on task top-level then posts reply with thread_ts", async () => {
    const slack = makeMockSlack("ts-reply-task-001");
    const store = new InMemoryThreadStore();
    await store.setTaskThread(WORKSPACE_ID, FEATURE_ID, TASK_ID, "ts-task-100");
    const events: NotificationEvent[] = [];
    const svc = makeService(slack, store, events);

    await svc.postTaskMessage(FEATURE_ID, TASK_ID, "task_status_changed", {
      ...TASK_CTX,
      status: "in_review",
    });

    expect(slack.updateMessage).toHaveBeenCalledOnce();
    const updateArgs = (slack.updateMessage as ReturnType<typeof vi.fn>).mock.calls[0];
    expect(updateArgs[0]).toBe("ts-task-100");
    expect(updateArgs[1]).toContain("Status: :mag: in_review");

    expect(slack.postMessage).toHaveBeenCalledOnce();
    const replyArgs = (slack.postMessage as ReturnType<typeof vi.fn>).mock.calls[0];
    expect(replyArgs[0]).toContain("Type: task_status_changed");
    expect(replyArgs[1]).toEqual({ threadTs: "ts-task-100" });

    expect(events).toContainEqual({
      type: "task_slack_thread_updated",
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      threadTs: "ts-task-100",
    });
    expect(events).toContainEqual({
      type: "task_slack_reply_posted",
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      threadTs: "ts-task-100",
    });
  });

  it("task_pr_changed includes pr url in update and reply", async () => {
    const slack = makeMockSlack();
    const store = new InMemoryThreadStore();
    await store.setTaskThread(WORKSPACE_ID, FEATURE_ID, TASK_ID, "ts-task-100");
    const svc = makeService(slack, store);

    await svc.postTaskMessage(FEATURE_ID, TASK_ID, "task_pr_changed", {
      ...TASK_CTX,
      pr: { url: "https://github.com/org/repo/pull/10", status: "open" },
    });

    const updateText = (slack.updateMessage as ReturnType<typeof vi.fn>).mock.calls[0][1] as string;
    expect(updateText).toContain("PR: https://github.com/org/repo/pull/10 (open)");
  });

  it("lazily creates task thread on non-start trigger when key is missing", async () => {
    const slack = makeMockSlack("ts-task-lazy");
    const store = new InMemoryThreadStore();
    const events: NotificationEvent[] = [];
    const svc = makeService(slack, store, events);

    await svc.postTaskMessage(FEATURE_ID, TASK_ID, "task_status_changed", TASK_CTX);

    expect(slack.postMessage).toHaveBeenCalledOnce(); // creates thread
    expect(slack.updateMessage).not.toHaveBeenCalled();
    expect(events).toContainEqual({
      type: "task_slack_thread_created",
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      threadTs: "ts-task-lazy",
    });
  });

  it("task message NEVER routes into the feature thread", async () => {
    const slack = makeMockSlack("ts-task-100");
    const store = new InMemoryThreadStore();
    // Feature thread exists — task message must NOT use it
    await store.setFeatureThread(WORKSPACE_ID, FEATURE_ID, "ts-feat-SHOULD-NOT-USE");
    const events: NotificationEvent[] = [];
    const svc = makeService(slack, store, events);

    await svc.postTaskMessage(FEATURE_ID, TASK_ID, "task_start", TASK_CTX);

    const calls = (slack.postMessage as ReturnType<typeof vi.fn>).mock.calls;
    for (const call of calls) {
      expect(call[1]?.threadTs).not.toBe("ts-feat-SHOULD-NOT-USE");
    }
    const updateCalls = (slack.updateMessage as ReturnType<typeof vi.fn>).mock.calls;
    for (const call of updateCalls) {
      expect(call[0]).not.toBe("ts-feat-SHOULD-NOT-USE");
    }
  });

  it("does not call Slack when not configured", async () => {
    const events: NotificationEvent[] = [];
    const svc = makeService(null, null, events);

    await svc.postTaskMessage(FEATURE_ID, TASK_ID, "task_status_changed", TASK_CTX);

    expect(events[0]).toMatchObject({ type: "slack_notification_skipped" });
  });
});

// ══════════════════════════════════════════════════════════════════════════════
// closeFeatureThread
// ══════════════════════════════════════════════════════════════════════════════

describe("closeFeatureThread", () => {
  it("calls chat.update + reply + deletes feature Redis key", async () => {
    const slack = makeMockSlack();
    const store = new InMemoryThreadStore();
    await store.setFeatureThread(WORKSPACE_ID, FEATURE_ID, "ts-feat-100");
    const events: NotificationEvent[] = [];
    const svc = makeService(slack, store, events);

    await svc.closeFeatureThread(FEATURE_ID, {
      ...FEATURE_CTX,
      status: "done",
    });

    expect(slack.updateMessage).toHaveBeenCalledOnce();
    expect(slack.postMessage).toHaveBeenCalledOnce();

    const remaining = await store.getFeatureThread(WORKSPACE_ID, FEATURE_ID);
    expect(remaining).toBeNull();

    expect(events).toContainEqual({
      type: "feature_slack_thread_deleted",
      featureId: FEATURE_ID,
    });
  });

  it("emits feature_slack_thread_delete_failed when delete throws, and does not throw", async () => {
    const slack = makeMockSlack();
    const store = {
      getFeatureThread: vi.fn().mockResolvedValue("ts-feat-100"),
      setFeatureThread: vi.fn(),
      deleteFeatureThread: vi.fn().mockRejectedValue(new Error("Redis timeout")),
      getTaskThread: vi.fn().mockResolvedValue(null),
      setTaskThread: vi.fn(),
      deleteTaskThread: vi.fn(),
      deleteAllTaskThreads: vi.fn().mockResolvedValue(undefined),
    };
    const events: NotificationEvent[] = [];
    const svc = makeService(slack, store as unknown as InMemoryThreadStore, events);

    await expect(
      svc.closeFeatureThread(FEATURE_ID, { ...FEATURE_CTX, status: "done" }),
    ).resolves.toBeUndefined();

    expect(events).toContainEqual({
      type: "feature_slack_thread_delete_failed",
      featureId: FEATURE_ID,
      reason: expect.stringContaining("Redis timeout"),
    });
  });
});

// ══════════════════════════════════════════════════════════════════════════════
// closeTaskThread
// ══════════════════════════════════════════════════════════════════════════════

describe("closeTaskThread", () => {
  it("calls chat.update + reply + deletes task Redis key", async () => {
    const slack = makeMockSlack();
    const store = new InMemoryThreadStore();
    await store.setTaskThread(WORKSPACE_ID, FEATURE_ID, TASK_ID, "ts-task-100");
    const events: NotificationEvent[] = [];
    const svc = makeService(slack, store, events);

    await svc.closeTaskThread(FEATURE_ID, TASK_ID, {
      ...TASK_CTX,
      status: "done",
    });

    expect(slack.updateMessage).toHaveBeenCalledOnce();
    expect(slack.postMessage).toHaveBeenCalledOnce();
    const replyArgs = (slack.postMessage as ReturnType<typeof vi.fn>).mock.calls[0];
    expect(replyArgs[0]).toContain("Type: task_completed");
    expect(replyArgs[1]).toEqual({ threadTs: "ts-task-100" });

    const remaining = await store.getTaskThread(WORKSPACE_ID, FEATURE_ID, TASK_ID);
    expect(remaining).toBeNull();

    expect(events).toContainEqual({
      type: "task_slack_thread_deleted",
      featureId: FEATURE_ID,
      taskId: TASK_ID,
    });
  });

  it("emits task_slack_thread_delete_failed when delete throws, and does not throw", async () => {
    const slack = makeMockSlack();
    const store = {
      getFeatureThread: vi.fn(),
      setFeatureThread: vi.fn(),
      deleteFeatureThread: vi.fn(),
      getTaskThread: vi.fn().mockResolvedValue("ts-task-100"),
      setTaskThread: vi.fn(),
      deleteTaskThread: vi.fn().mockRejectedValue(new Error("Redis gone")),
      deleteAllTaskThreads: vi.fn(),
    };
    const events: NotificationEvent[] = [];
    const svc = makeService(slack, store as unknown as InMemoryThreadStore, events);

    await expect(
      svc.closeTaskThread(FEATURE_ID, TASK_ID, { ...TASK_CTX, status: "done" }),
    ).resolves.toBeUndefined();

    expect(events).toContainEqual({
      type: "task_slack_thread_delete_failed",
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      reason: expect.stringContaining("Redis gone"),
    });
  });
});

// ══════════════════════════════════════════════════════════════════════════════
// Slack API failure handling
// ══════════════════════════════════════════════════════════════════════════════

describe("Slack API failure handling", () => {
  it("emits slack_notification_failed when postMessage throws during thread creation", async () => {
    const slack = {
      postMessage: vi.fn().mockRejectedValue(new Error("Slack 500")),
      updateMessage: vi.fn(),
    } as unknown as SlackWebApiClient;
    const store = new InMemoryThreadStore();
    const events: NotificationEvent[] = [];
    const svc = makeService(slack, store, events);

    const ts = await svc.ensureFeatureThread(FEATURE_ID, FEATURE_CTX);

    expect(ts).toBeNull();
    expect(events).toContainEqual({
      type: "slack_notification_failed",
      reason: expect.stringContaining("Slack 500"),
    });
  });

  it("emits slack_notification_failed when chat.update throws but continues to post reply", async () => {
    const slack = {
      postMessage: vi.fn().mockResolvedValue({ ts: "ts-reply", channel: "C123" }),
      updateMessage: vi.fn().mockRejectedValue(new Error("update failed")),
    } as unknown as SlackWebApiClient;
    const store = new InMemoryThreadStore();
    await store.setFeatureThread(WORKSPACE_ID, FEATURE_ID, "ts-feat-100");
    const events: NotificationEvent[] = [];
    const svc = makeService(slack, store, events);

    await svc.postFeatureMessage(FEATURE_ID, "feature_summary_changed", FEATURE_CTX);

    expect(events.some((e) => e.type === "slack_notification_failed")).toBe(true);
    // Reply is still attempted even though update failed
    expect(slack.postMessage).toHaveBeenCalledOnce();
  });

  it("emits slack_notification_failed when reply postMessage throws", async () => {
    const slack = {
      postMessage: vi.fn().mockRejectedValue(new Error("postMessage failed")),
      updateMessage: vi.fn().mockResolvedValue(undefined),
    } as unknown as SlackWebApiClient;
    const store = new InMemoryThreadStore();
    await store.setTaskThread(WORKSPACE_ID, FEATURE_ID, TASK_ID, "ts-task-100");
    const events: NotificationEvent[] = [];
    const svc = makeService(slack, store, events);

    await svc.postTaskMessage(FEATURE_ID, TASK_ID, "task_status_changed", TASK_CTX);

    expect(events.some((e) => e.type === "slack_notification_failed")).toBe(true);
  });
});

